parameters.query:
SELECT id, name, email, phone, position, skills, experience_years, status, created_at
FROM candidates
WHERE id = $1;

INSERT INTO pending_actions (action, candidate_id, payload)
VALUES ('update_status', $1, jsonb_build_object('new_status', $2))
RETURNING id, status;

INSERT INTO pending_actions (action, candidate_id, payload)
VALUES ('send_email', $1, jsonb_build_object('to', $2, 'subject', $3, 'body', $4))
RETURNING id, status;
